<script lang="ts">
	import { enhance } from '$app/forms';
	import { page } from '$app/stores';
	import { fullName, record, records } from '$lib/api';
	import { t } from '$lib/i18n';
	let { data, form }: any = $props();
	let locale = $derived(data.locale ?? 'en');
	let path = $derived(data.path ?? '/');
	let resource = $derived(record(data.resource) ?? data.resource);
	let failure = $derived(form?.error ?? data.error);
	const tr = (key: string) => t(locale, key);
	const list = $derived(records(data.resource));
	const user = $derived(data.user);
	const profile = (value: any) => value?.expand?.user ?? value?.user ?? value;
	const label = (value: string) => value.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
	const fmtDate = (value?: string) => value ? new Intl.DateTimeFormat(locale, { dateStyle: 'medium' }).format(new Date(value)) : '—';
	const recordsOf = (value: any) => records(value);
	const pageCount = (value: any, fallback = 5) => Math.max(1, Number(value?.total_pages ?? Math.ceil(Number(value?.total ?? 0) / Number(value?.per_page ?? fallback))));
	const getResourceItems = (value: any) => records(value?.items);
	const queryValue = (key: string) => $page.url.searchParams.get(key) ?? '';
	const planType = (value: any) => $page.url.searchParams.get('plan_type') ?? value?.plan_type ?? value?.type ?? 'training';
	const arrayValue = (value: any) => Array.isArray(value) ? value : [];
	function confirmDelete(event: SubmitEvent) {
		if (!window.confirm('Delete this record? This cannot be undone.')) event.preventDefault();
	}
	function textValue(value: any, key: string) { return value?.[key] ?? ''; }
	function metrics(value: any) {
		const source = value?.stats ?? value?.overall ?? value ?? {};
		if (!source || typeof source !== 'object') return [];
		return Object.entries(source).filter(([, item]) => typeof item === 'number' || typeof item === 'string').slice(0, 8);
	}
</script>

<svelte:head>
	<title>{path === '/login' ? `${tr('Log in')} · ${data.tenantName ?? 'Gyme'}` : `${label(path.split('/').filter(Boolean).at(-1) ?? 'Dashboard')} · ${data.tenantName ?? 'Gyme'}`}</title>
</svelte:head>

{#if path === '/login'}
	<section class="login-layout">
		<div class="login-art"><span class="art-kicker">{data.tenantName ?? 'GYME'} / COACHING SYSTEM</span><h1>Strength<br />in the<br /><em>details.</em></h1><p>Better coaching starts with a clearer picture.</p><span class="art-orbit" aria-hidden="true"></span></div>
		<div class="login-form-wrap">
			<a class="brand brand-dark" href="/login">{#if data.tenantLogo}<img class="brand-logo" src={data.tenantLogo} alt="" />{:else}<span class="brand-mark">G</span>{/if}<span>{data.tenantName ?? 'GYME'}</span></a>
