				<label>{tr('Password')}<input type="password" name="password" autocomplete="current-password" required maxlength="128" /></label>
				<input type="hidden" name="next" value={$page.url.searchParams.get('next') ?? ''} />
				<button class="button primary wide" type="submit">{tr('Log in')} <span aria-hidden="true">↗</span></button>
			</form>
			<p class="form-note">Your gym workspace is private to your team.</p>
		</div>
	</section>
{:else if path === '/change-password'}
