			<label>{tr('New password')}<input type="password" name="new_password" required minlength="8" maxlength="72" autocomplete="new-password" /></label>
			<label>{tr('Confirm password')}<input type="password" name="confirm_password" required minlength="8" maxlength="72" autocomplete="new-password" /></label>
			<button class="button primary" type="submit">{tr('Save changes')}</button>
		</form>
	</section>
{:else if failure}
