			<form method="GET" action="/dashboard" class="select-inline"><label for="timeframe">{tr('Time period')}</label><select id="timeframe" name="timeframe" value={queryValue('timeframe') || 'all'} onchange={(event) => event.currentTarget.form?.requestSubmit()}><option value="all">{tr('All time')}</option><option value="month">{tr('This month')}</option><option value="week">{tr('This week')}</option></select></form>
		</div>
		<div class="metric-grid">{#each metrics(resource?.stats ?? resource) as [key, value]}<article class="metric"><span>{label(String(key))}</span><strong>{value}</strong></article>{:else}<p class="empty wide-empty">{tr('No records yet')}</p>{/each}</div>
		{#if path === '/dashboard/coach-stats'}<div class="records-list">{#each recordsOf(resource) as coach}<a class="person-row" href={coach.id ? `/coaches/${coach.id}` : '/dashboard'}><span class="person-mark">{fullName(coach).slice(0, 1)}</span><span class="person-main"><strong>{fullName(coach)}</strong><small>{coach.plan_count ?? 0} {tr('Plans')} · {coach.active_plans ?? 0} {tr('Active')}</small></span><span class="row-arrow">↗</span></a>{:else}<div class="empty">{tr('No records yet')}</div>{/each}</div>{/if}
		{#if user?.role === 'owner' && Array.isArray(resource?.coach_stats)}
