			<div class="form-actions"><a class="button outline" href={editing ? `/trainees/${trainee?.id}` : '/trainees'}>{tr('Cancel')}</a>{#if editing}<button class="button danger" type="submit" name="intent" value="delete" formaction="?/submit" onclick={(event) => { if (!window.confirm('Delete this trainee? This cannot be undone.')) event.preventDefault(); }}>{tr('Delete')}</button>{/if}<button class="button primary" type="submit">{editing ? tr('Save changes') : tr('Save')}</button></div>
		</form>
	</section>
{:else if /^\/trainees\/[^/]+$/.test(path)}
	{@const trainee = resource}{@const person = profile(trainee)}
	<section class="page"><a class="backlink" href="/trainees">← {tr('Trainees')}</a><div class="detail-heading"><span class="person-mark large">{fullName(person).slice(0, 1)}</span><div><span class="eyebrow">TRAINEE PROFILE</span><h1>{fullName(person)}</h1><p>{person?.email} {person?.phone ? ` · ${person.phone}` : ''}</p></div><a class="button outline" href={`/trainees/${trainee?.id}/edit`}>{tr('Edit')}</a></div>
		<div class="detail-grid"><article class="panel"><span class="eyebrow">ABOUT</span><dl><dt>{tr('Gender')}</dt><dd>{trainee?.gender ?? '—'}</dd><dt>{tr('Birth date')}</dt><dd>{fmtDate(trainee?.birthdate)}</dd><dt>{tr('Blood type')}</dt><dd>{trainee?.blood_type ?? '—'}</dd><dt>{tr('Height')} / {tr('Weight')}</dt><dd>{trainee?.height ?? '—'} / {trainee?.weight ?? '—'}</dd></dl>{#each ['training_history', 'steroid_history', 'supplement_history', 'limitations', 'notes'] as field}{#if trainee?.[field]}<h3>{label(field)}</h3><p>{trainee[field]}</p>{/if}{/each}</article><div class="detail-side"><div class="section-heading"><h2>{tr('Plans')}</h2><a href={`/plans/new?trainee=${trainee?.id}`}>＋ {tr('New plan')}</a></div>{#each recordsOf(trainee?.plans ?? trainee?.expand?.plans) as plan}<a class="compact-row" href={`/plans/${plan.id}`}><span class="type-dot"></span><span><strong>{plan.title ?? label(plan.type ?? 'Plan')}</strong><small>{tr(plan.type ?? 'Plan')} · {plan.status ?? '—'}</small></span><span>↗</span></a>{:else}<div class="empty">{tr('No records yet')}</div>{/each}{#if user?.role !== 'trainee'}<a class="button outline wide" href={`/progress-log/new/${trainee?.id}`}>{tr('Record assessment')}</a>{/if}<div class="section-heading"><h2>{tr('Progress assessment')}</h2></div>{#each recordsOf(trainee?.progress_logs) as log}<a class="compact-row" href={`/progress-log/${log.id}/edit`}><span><strong>{fmtDate(log.created ?? log.date)}</strong><small>{tr('Weight')}: {log.weight ?? '—'} kg · BMI {log.bmi ?? '—'}</small></span><span>↗</span></a>{:else}<div class="empty">{tr('No records yet')}</div>{/each}</div></div>
	</section>
{:else if /^\/coaches\/new$/.test(path) || /^\/coaches\/[^/]+\/edit$/.test(path)}
	{@const editing = path !== '/coaches/new'}{@const coach = editing ? resource : null}
