		<form method="POST" action="?/submit" use:enhance class="form-stack panel"><div class="two-col"><label>{tr('First name')}<input name="first_name" required maxlength="50" value={coach?.first_name ?? ''} /></label><label>{tr('Last name')}<input name="last_name" required maxlength="50" value={coach?.last_name ?? ''} /></label></div><label>{tr('Email')}<input name="email" type="email" required readonly={editing} value={coach?.email ?? ''} /></label><label>{tr('Phone')}<input name="phone" type="tel" value={coach?.phone ?? ''} /></label><div class="form-actions"><a class="button outline" href="/coaches">{tr('Cancel')}</a>{#if editing}<button class="button danger" type="submit" name="intent" value="delete" onclick={(event) => { if (!window.confirm('Delete this coach? This cannot be undone.')) event.preventDefault(); }}>{tr('Delete')}</button>{/if}<button class="button primary" type="submit">{editing ? tr('Save changes') : tr('Add coach')}</button></div></form>
	</section>
