lse}<div class="empty">{tr('No records yet')}<a href={`/plans/new${templatesOnly ? '?template=true' : ''}`}>{tr('Create plan')}</a></div>{/each}</div>{#if pageCount(data.resource) > 1}<nav class="pagination"><span>{data.resource?.total ?? list.length} records</span><div>{#each Array.from({ length: pageCount(data.resource) }, (_, i) => i + 1) as current}<a class:current={current === Number(queryValue('page') || 1)} href={`?${new URLSearchParams({ ...Object.fromEntries($page.url.searchParams), page: String(current) })}`}>{current}</a>{/each}</div></nav>{/if}</section>
{:else if /^\/plans\/new$/.test(path) || /^\/plans\/[^/]+\/edit$/.test(path)}
