		<form method="POST" action="?/submit" use:enhance class="form-stack panel"><input type="hidden" name="is_template" value={isTemplate ? 'true' : 'false'} />{#if isTemplate}<label>{tr('Template name')}<input name="template_name" maxlength="100" required value={plan?.template_name ?? ''} /></label>{/if}<label>{tr('Plan type')}<select name="type" value={plan?.type ?? 'training'}><option value="training">{tr('Training')}</option><option value="diet">{tr('Diet')}</option><option value="steroid">{tr('Steroid')}</option></select></label><label>{tr('Coach')}<select name="coach" value={plan?.coach ?? user?.id ?? ''}><option value={user?.id}>{fullName(user)}</option>{#each data.lists?.coaches ?? [] as coach}{#if coach.id !== user?.id}<option value={coach.id}>{fullName(coach)}</option>{/if}{/each}</select></label>{#if !isTemplate}<label>{tr('Trainee')}<select name="trainee" required value={plan?.trainee ?? $page.url.searchParams.get('trainee') ?? ''}><option value="">Choose a trainee</option>{#each data.lists?.trainees ?? [] as trainee}<option value={trainee.id}>{fullName(trainee)}</option>{/each}</select></label><div class="two-col"><label>{tr('Start date')}<input type="date" name="start_date" value={plan?.start_date?.slice(0, 10) ?? ''} /></label><label>{tr('End date')}<input type="date" name="end_date" value={plan?.end_date?.slice(0, 10) ?? ''} /></label></div>{/if}<div class="two-col"><label>{tr('Days per week')}<input type="number" name="days_per_week" min="1" max="7" value={plan?.days_per_week ?? 3} /></label><label>{tr('Status')}<select name="status" value={plan?.status ?? 'active'}><option value="active">{tr('Active')}</option><option value="inactive">{tr('Inactive')}</option></select></label></div><label>{tr('Notes')}<textarea name="notes" rows="3" maxlength="1000">{plan?.notes ?? ''}</textarea></label><div class="form-actions"><a class="button outline" href="/plans">{tr('Cancel')}</a>{#if editing}<button class="button danger" type="submit" name="intent" value="delete" onclick={(event) => { if (!window.confirm('Delete this plan? This cannot be undone.')) event.preventDefault(); }}>{tr('Delete')}</button>{/if}<button class="button primary" type="submit">{editing ? tr('Save changes') : tr('Create plan')}</button></div></form>
	</section>
{:else if /^\/templates\/[^/]+\/apply$/.test(path)}
	<section class="page narrow"><a class="backlink" href={`/plans/${resource?.id}`}>← {tr('Plan templates')}</a><div class="page-heading"><span class="eyebrow">TEMPLATE / ASSIGN</span><h1>{tr('Apply to trainee')}</h1><p>{resource?.template_name ?? resource?.title ?? tr('Plan templates')}</p></div>{#if failure}<div class="notice error" role="alert">{failure}</div>{/if}<form method="POST" action="?/submit" use:enhance class="form-stack panel"><label>{tr('Trainee')}<select name="trainee" required><option value="">Choose a trainee</option>{#each data.lists?.trainees ?? [] as trainee}<option value={trainee.id}>{fullName(trainee)}</option>{/each}</select></label><label>{tr('Coach')}<select name="coach" value={user?.id}>{#each data.lists?.coaches ?? [] as coach}<option value={coach.id}>{fullName(coach)}</option>{/each}</select></label><div class="two-col"><label>{tr('Start date')}<input type="date" name="start_date" /></label><label>{tr('End date')}<input type="date" name="end_date" /></label></div><label>{tr('Notes')}<textarea name="notes" rows="3"></textarea></label><button class="button primary" type="submit">{tr('Apply to trainee')}</button></form></section>
{:else if /^\/plans\/[^/]+$/.test(path)}
	{@const plan = resource}{@const items = getResourceItems(plan)}{@const isTemplate = Boolean(plan?.is_template)}
	<section class="page"><a class="backlink" href="/plans">← {tr('Plans')}</a><div class="detail-heading"><span class="plan-glyph large-glyph">{(plan?.type ?? 'P').slice(0, 1).toUpperCase()}</span><div><span class="eyebrow">{isTemplate ? tr('Plan templates') : tr('Plans')}</span><h1>{plan?.template_name ?? plan?.title ?? fullName(plan?.expand?.trainee)}</h1><p>{tr(plan?.type ?? 'Plan')} · {plan?.status ?? '—'}</p></div><a class="button outline" href={`/plans/${plan?.id}/edit`}>{tr('Edit')}</a></div>
		<div class="detail-grid"><article class="panel"><span class="eyebrow">PROGRAM DETAILS</span><dl><dt>{tr('Coach')}</dt><dd>{fullName(plan?.expand?.coach) || plan?.coach_name || '—'}</dd>{#if !isTemplate}<dt>{tr('Trainee')}</dt><dd>{fullName(plan?.expand?.trainee) || plan?.trainee_name || '—'}</dd><dt>{tr('Start date')}</dt><dd>{fmtDate(plan?.start_date)}</dd><dt>{tr('End date')}</dt><dd>{fmtDate(plan?.end_date)}</dd>{/if}<dt>{tr('Days per week')}</dt><dd>{plan?.days_per_week ?? '—'}</dd></dl>{#if plan?.notes}<p>{plan.notes}</p>{/if}{#if isTemplate}<a class="button primary wide" href={`/templates/${plan?.id}/apply`}>{tr('Apply to trainee')}</a>{/if}</article><div><div class="section-heading"><h2>{tr('Plan items')}</h2><a href={`/items/new?plan_type=${plan?.type}&plan_id=${plan?.id}`}>＋ {tr('Add item')}</a></div><div class="item-list">{#each items as item (item.id)}<article class="item-row"><div><span class="eyebrow">{plan?.type === 'training' ? `${tr('Training')} · ${tr('Day')} ${item.seq ?? 1}` : tr(plan?.type ?? 'Plan')}</span><h3>{item.name ?? item.item_name ?? item.meal_name ?? '—'}</h3><p>{#if plan?.type === 'training'}{item.sets ?? '—'} sets · {item.reps ?? '—'} reps · {item.weight ?? '—'} kg{:else if plan?.type === 'diet'}{item.quantity ?? ''}{:else}{item.dosage ?? item.frequency ?? ''}{/if}</p>{#if item.notes}<small>{item.notes}</small>{/if}</div><div class="item-actions"><a href={`/items/${item.id}/edit?plan_type=${plan?.type}`}>{tr('Edit')}</a><form method="POST" action={`/items/${item.id}?/submit`} use:enhance><input type="hidden" name="intent" value="delete" /><input type="hidden" name="plan" value={plan?.id} /><input type="hidden" name="plan_type" value={plan?.type} /><button class="link-danger" type="submit" onclick={(event) => { if (!window.confirm('Delete this item?')) event.preventDefault(); }}>{tr('Delete')}</button></form></div></article>{:else}<div class="empty">{tr('No records yet')}<a href={`/items/new?plan_type=${plan?.type}&plan_id=${plan?.id}`}>{tr('Add item')}</a></div>{/each}</div></div></div>
	</section>
{:else if path === '/items/new' || /^\/items\/[^/]+\/edit$/.test(path)}
	{@const editing = path !== '/items/new'}{@const item = editing ? resource : null}{@const type = planType(item)}{@const planId = item?.plan ?? $page.url.searchParams.get('plan_id') ?? ''}
	<section class="page narrow"><a class="backlink" href={`/plans/${planId}`}>← {tr('Plans')}</a><div class="page-heading"><span class="eyebrow">PROGRAMMING / ITEM</span><h1>{editing ? tr('Edit item') : tr('Add item')}</h1><p>{tr(type)} · {resource?.title ?? resource?.template_name ?? ''}</p></div>{#if failure}<div class="notice error" role="alert">{failure}</div>{/if}<form method="POST" action="?/submit" use:enhance class="form-stack panel"><input type="hidden" name="plan_type" value={type} /><input type="hidden" name="plan" value={planId} />
			{#if type === 'training'}<label>{tr('Exercise')}<input name="item_name" required value={item?.name ?? ''} /></label><div class="three-col"><label>{tr('Day')}<input type="number" name="seq" min="1" value={item?.seq ?? 1} /></label><label>{tr('Sets')}<input type="number" name="sets" min="1" value={item?.sets ?? ''} /></label><label>{tr('Reps')}<input type="number" name="reps" min="1" value={item?.reps ?? ''} /></label></div><div class="two-col"><label>{tr('Weight')} (kg)<input type="number" name="weight" min="0" step="0.5" value={item?.weight ?? ''} /></label><label>{tr('Rest')} (sec)<input type="number" name="rest_seconds" min="0" value={item?.rest_seconds ?? ''} /></label></div><label>{tr('Category')}<input name="category" value={item?.category ?? ''} /></label>
			{:else if type === 'diet'}<label>{tr('Meal')}<input name="meal_name" required value={item?.meal_name ?? ''} /></label><label>{tr('Food')}<input name="food_name" required value={item?.name ?? ''} /></label><label>{tr('Quantity')}<input name="quantity" value={item?.quantity ?? ''} /></label><label>{tr('Day')}<input type="number" name="seq" min="1" value={item?.seq ?? 1} /></label>
			{:else}<label>{tr('Name')}<input name="name" required value={item?.name ?? ''} /></label><label>{tr('Type')}<input name="type" value={item?.type ?? ''} /></label><label>{tr('Dosage')}<input name="dosage" value={item?.dosage ?? ''} /></label><label>{tr('Frequency')}<input name="frequency" value={item?.frequency ?? ''} /></label><label>{tr('Day')}<input type="number" name="seq" min="1" value={item?.seq ?? 1} /></label>{/if}<label>{tr('Notes')}<textarea name="notes" rows="3" maxlength="1000">{item?.notes ?? ''}</textarea></label><div class="form-actions"><a class="button outline" href={`/plans/${planId}`}>{tr('Cancel')}</a>{#if editing}<button class="button danger" type="submit" name="intent" value="delete" onclick={(event) => { if (!window.confirm('Delete this item?')) event.preventDefault(); }}>{tr('Delete')}</button>{/if}<button class="button primary" type="submit">{tr('Save')}</button></div></form></section>
{:else if /^\/progress-log\/new\/[^/]+$/.test(path) || /^\/progress-log\/[^/]+\/edit$/.test(path)}
	{@const logEdit = path.includes('/edit')}{@const log = logEdit ? resource : null}{@const trainee = logEdit ? resource?.trainee_record : resource}{@const logTrainee = resource?.expand?.trainee ?? trainee}
	<section class="page narrow"><a class="backlink" href={logTrainee?.id ? `/trainees/${logTrainee.id}` : '/trainees'}>← {tr('Trainees')}</a><div class="page-heading"><span class="eyebrow">MEASURE / TRACK</span><h1>{logEdit ? tr('Edit assessment') : tr('Progress assessment')}</h1><p>{fullName(logTrainee)}</p></div>{#if failure}<div class="notice error" role="alert">{failure}</div>{/if}<form method="POST" action="?/submit" use:enhance enctype="multipart/form-data" class="form-stack panel"><input type="hidden" name="trainee" value={logTrainee?.id ?? path.split('/').at(-1)} /><div class="two-col"><label>{tr('Height')} (cm)<input type="number" name="height" min="30" max="300" step="0.1" required value={log?.height ?? ''} /></label><label>{tr('Weight')} (kg)<input type="number" name="weight" min="20" max="500" step="0.1" required value={log?.weight ?? ''} /></label></div><div class="three-col">{#each ['chest', 'waist', 'hip', 'arms', 'bmi', 'bfp', 'bmr', 'tdee', 'lbm', 'whr'] as metric}<label>{label(metric)}<input type="number" name={metric} min="0" step="0.1" value={log?.[metric] ?? ''} /></label>{/each}</div><label>{tr('Notes')}<textarea name="notes" rows="3" maxlength="1000">{log?.notes ?? ''}</textarea></label><label>{tr('Progress photos')}<input type="file" name="progress_photos" accept="image/jpeg,image/png,image/webp,image/gif" multiple /></label><div class="form-actions"><a class="button outline" href={logTrainee?.id ? `/trainees/${logTrainee.id}` : '/trainees'}>{tr('Cancel')}</a><button class="button primary" type="submit">{tr('Record assessment')}</button></div></form></section>
{:else if path === '/user/dashboard' || path === '/user/plans' || /^\/user\/plans\/[^/]+$/.test(path)}
	{@const userPlans = path === '/user/dashboard' ? (resource?.plans ?? {}) : resource}{@const detail = /^\/user\/plans\/[^/]+$/.test(path)}{@const allPlans = Array.isArray(userPlans) ? userPlans : Object.values(userPlans ?? {}).flatMap((value: any) => recordsOf(value))}
	<section class="page"><div class="page-heading split"><div><span class="eyebrow">YOUR TRAINING / GYME</span><h1>{detail ? (resource?.title ?? tr('Plans')) : path === '/user/dashboard' ? `${tr('Welcome back')}${user?.first_name ? `, ${user.first_name}` : ''}` : tr('Your plans')}</h1><p>{detail ? tr(resource?.type ?? 'Plan') : 'Your coach’s plan, ready when you are.'}</p></div>{#if !detail}<a class="button outline" href="/user/profile">{tr('Profile')}</a>{/if}</div>
		{#if detail}<div class="detail-grid"><article class="panel"><span class="eyebrow">{tr('Plan type')}</span><h2>{tr(resource?.type ?? 'Plan')}</h2><dl><dt>{tr('Start date')}</dt><dd>{fmtDate(resource?.start_date)}</dd><dt>{tr('End date')}</dt><dd>{fmtDate(resource?.end_date)}</dd><dt>{tr('Days per week')}</dt><dd>{resource?.days_per_week ?? '—'}</dd></dl></article><div class="item-list">{#each getResourceItems(resource) as item}<article class="item-row"><div><span class="eyebrow">{tr('Day')} {item.seq ?? 1}</span><h3>{item.name ?? item.meal_name ?? '—'}</h3><p>{item.sets ? `${item.sets} sets · ${item.reps} reps` : item.quantity ?? item.dosage ?? ''}</p></div></article>{/each}<form method="POST" action={`/user/plans/${resource?.id}/done?/submit`} use:enhance><button class="button primary wide" type="submit">{tr('Complete this day')} <span aria-hidden="true">↗</span></button></form></div></div>
		{:else}<div class="plan-categories">{#each ['training', 'diet', 'steroid'] as category}{@const entries = recordsOf((userPlans as any)?.[category])}<section><div class="section-heading"><h2>{tr(category === 'steroid' ? 'Steroid' : category.charAt(0).toUpperCase() + category.slice(1))}</h2><span>{entries.length}</span></div>{#each entries as plan (plan.id)}<a class="assignment-card" href={`/user/plans/${plan.id}`}><span class="plan-glyph">{category.slice(0, 1).toUpperCase()}</span><span><strong>{plan.title ?? plan.name ?? tr(category)}</strong><small>{fmtDate(plan.start_date)} – {fmtDate(plan.end_date)}</small></span><span class="row-arrow">↗</span></a>{:else}<div class="empty">{tr('No records yet')}</div>{/each}</section>{/each}</div>{/if}
	</section>
{:else if path === '/profile' || path === '/user/profile'}
	{@const person = resource?.user ?? resource}
	<section class="page narrow"><div class="page-heading"><span class="eyebrow">ACCOUNT / PERSONAL</span><h1>{tr('Profile')}</h1><p>Keep your contact details up to date.</p></div>{#if failure}<div class="notice error" role="alert">{failure}</div>{/if}<form method="POST" action="?/submit" use:enhance class="form-stack panel"><div class="two-col"><label>{tr('First name')}<input name="first_name" required value={person?.first_name ?? ''} /></label><label>{tr('Last name')}<input name="last_name" required value={person?.last_name ?? ''} /></label></div><label>{tr('Email')}<input name="email" type="email" value={person?.email ?? ''} readonly /></label><label>{tr('Phone')}<input name="phone" type="tel" value={person?.phone ?? ''} /></label><div class="form-actions"><a class="button outline" href="/change-password">{tr('Change password')}</a><button class="button primary" type="submit">{tr('Save changes')}</button></div></form></section>
{:else}
	<section class="page state-page"><span class="state-mark">?</span><h1>Page not found</h1><p>This part of the coaching space doesn’t exist.</p><a class="button primary" href={user?.role === 'trainee' ? '/user/dashboard' : '/dashboard'}>{tr('Dashboard')}</a></section>
{/if}
